const wait = (ms, value, fail = false) =>
  new Promise((resolve, reject) => setTimeout(() => (fail ? reject(new Error(value)) : resolve(value)), ms));

async function loadDashboard() {
  const started = Date.now();
  const [user, orders] = await Promise.all([wait(100, 'Asha'), wait(100, ['o1', 'o2'])]);
  const [recs] = await Promise.allSettled([wait(20, 'recs down', true)]);
  return {
    user,
    orders,
    recommendations: recs.status === 'fulfilled' ? recs.value : [],
    ms: Math.round((Date.now() - started) / 10) * 10
  };
}

loadDashboard().then(console.log);
// { user: 'Asha', orders: [ 'o1', 'o2' ], recommendations: [], ms: 120 } (approximately)

const t = (ms, v, fail) => new Promise((res, rej) => setTimeout(() => (fail ? rej(v) : res(v)), ms));
const make = () => [t(30, 'a'), t(10, 'b-error', true), t(20, 'c')];

Promise.all(make()).then(v => console.log('all', v), e => console.log('all rejected', e));
Promise.allSettled(make()).then(r => console.log('allSettled', r.map(x => x.status).join(',')));
Promise.race(make()).then(v => console.log('race', v), e => console.log('race rejected', e));
Promise.any(make()).then(v => console.log('any', v));

